<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Theme\Domain;

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeUidVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeTenantVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeTenantAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeNameVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeNameAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeIsDefaultVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeIsDefaultAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeEnabledVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeEnabledAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeCustomCssVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeCustomCssAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeVersionVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor\ThemeVersionAccessor;
use Civi\Lughauth\Features\Document\Theme\Domain\Event\ThemeCreateEvent;
use Civi\Lughauth\Features\Document\Theme\Domain\Event\ThemeUpdateEvent;
use Civi\Lughauth\Features\Document\Theme\Domain\Event\ThemeDeleteEvent;
use Civi\Lughauth\Features\Document\Theme\Domain\Event\ThemeEnableEvent;
use Civi\Lughauth\Features\Document\Theme\Domain\Event\ThemeDisableEvent;

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class Theme extends ThemeRef
{
  use ThemeTenantAccessor;
  use ThemeNameAccessor;
  use ThemeIsDefaultAccessor;
  use ThemeEnabledAccessor;
  use ThemeCustomCssAccessor;
  use ThemeVersionAccessor;
  private array $recordedEvents = [];

  public function __construct(
    ThemeUidVO|string $uid,
    ThemeTenantVO|TenantRef $tenant,
    ThemeNameVO|string $name,
    ThemeIsDefaultVO|bool|null $isDefault = null,
    ThemeEnabledVO|bool|null $enabled = null,
    ThemeCustomCssVO|string|null $customCss = null,
    ThemeVersionVO|int|null $version = null,
  ) {
    parent::__construct($uid);
    $this->_tenant = ThemeTenantVO::from($tenant);
    $this->_name = ThemeNameVO::from($name);
    $this->_isDefault = null === $isDefault ? ThemeIsDefaultVO::empty() : ThemeIsDefaultVO::from($isDefault);
    $this->_enabled = null === $enabled ? ThemeEnabledVO::empty() : ThemeEnabledVO::from($enabled);
    $this->_customCss = null === $customCss ? ThemeCustomCssVO::empty() : ThemeCustomCssVO::from($customCss);
    $this->_version = null === $version ? ThemeVersionVO::empty() : ThemeVersionVO::from($version);
  }
  public function replace(ThemeAttributes $values): Theme
  {
    $value = clone $this;
    $value->_tenant = $values->getTenantOrDefault($this->_tenant);
    $value->_name = $values->getNameOrDefault($this->_name);
    $value->_isDefault = $values->getIsDefaultOrDefault($this->_isDefault);
    $value->_enabled = $values->getEnabledOrDefault($this->_enabled);
    $value->_customCss = $values->getCustomCssOrDefault($this->_customCss);
    $value->_version = $values->getVersionOrDefault($this->_version);
    return $value;
  }
  public static function calculatedFields(): array
  {
    return [];
  }
  public static function create(ThemeAttributes $values): Theme
  {
    $value = $values->build();
    $value->recordedEvents[] = new ThemeCreateEvent($value);
    return $value;
  }
  public function update(ThemeAttributes $values): Theme
  {
    $value = $this->replace($values);
    $value->recordedEvents[] = new ThemeUpdateEvent($value, $this);
    return $value;
  }
  public function delete(): Theme
  {
    $value = clone $this;
    $value->recordedEvents[] = new ThemeDeleteEvent($value);
    return $value;
  }
  public function enable(): Theme
  {
    $value = clone $this;
    $value->_enabled = ThemeEnabledVO::from(true);
    $value->recordedEvents[] = new ThemeEnableEvent($value, original: $this);
    return $value;
  }
  public function disable(): Theme
  {
    $value = clone $this;
    $value->_enabled = ThemeEnabledVO::from(false);
    $value->recordedEvents[] = new ThemeDisableEvent($value, original: $this);
    return $value;
  }
  public function asPublicJson(): array
  {
    $data = [];
    $data['uid'] = $this->uid();
    $data['tenant'] = [ '$ref' => $this->getTenant()->uid() ];
    $data['name'] = $this->getName();
    $data['isDefault'] = $this->isIsDefault();
    $data['enabled'] = $this->isEnabled();
    $data['customCss'] = $this->getCustomCss();
    $data['version'] = $this->getVersion();
    return $data;
  }
  public function toAttributes(): ThemeAttributes
  {
    return (new ThemeAttributes())
      ->uid($this->uid())
      ->tenant($this->_tenant)
      ->name($this->_name)
      ->isDefault($this->_isDefault)
      ->enabled($this->_enabled)
      ->customCss($this->_customCss)
      ->version($this->_version);
  }
  public function getTheEvents(): array
  {
    return [...$this->recordedEvents];
  }
}
